        },
        {
          "kind": "paragraph",
          "text": "عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضيَ اللهُ عنهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ: «اللهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى، وَالْعَفَافَ وَالْغِنَى».",
          "role": "body",
          "sourceOnlyContext": true,
          "sourceLiteralProof": {
            "schema": "iman-source-literal-text-v1",
            "collection": "essential-hadith",
            "language": "ja",
