        {
          "kind": "paragraph",
          "text": "«وجعلته بينكم محرما فلا تظالموا»",
          "role": "body",
          "sourceOnlyContext": true,
          "sourceLiteralProof": {
            "schema": "iman-source-literal-text-v1",
